export type Deployment = (typeof DEPLOYMENTS)[NetworkId];

/** Narrows an untrusted string — a query param, localStorage — to a network. */
export function asNetwork(value: unknown): NetworkId | null {
  return typeof value === 'string' && (NETWORK_IDS as readonly string[]).includes(value)
    ? (value as NetworkId)
    : null;
}

/** Same, but never fails: anything unrecognised becomes the default. */
export function networkOrDefault(value: unknown): NetworkId {
  return asNetwork(value) ?? DEFAULT_NETWORK;
}

/** True once the contracts and accounts for this network actually exist. */
export function isConfigured(net: NetworkId): boolean {
  const d = DEPLOYMENTS[net];
  return Boolean(d.escrowId && d.usdcId && d.resolver && d.treasury);
}

/**
 * The config, or a refusal naming the network. Called by everything that is
 * about to talk to a chain, so an undeployed network fails here rather than as
 * an unreadable XDR error from a contract client built with an empty id.
 */
export function deployment(net: NetworkId): Deployment {
  if (!isConfigured(net)) {
    throw new Error(`No hay contratos desplegados en ${net}. Corré ./scripts/deploy.sh ${net}.`);
  }
  return DEPLOYMENTS[net];
}
